from pypdf import PdfReader
from docx import Document as DocxDocument
import chardet
from dataclasses import dataclass
from typing import List

@dataclass
class ExtractedPage:
    content: str
    page_number: int
    metadata: dict  # heading, source, etc.

class PDFExtractor:
    def extract(self, file_path: str) -> List[ExtractedPage]:
        reader = PdfReader(file_path)
        pages = []
        for i, page in enumerate(reader.pages):
            text = page.extract_text() or ""
            text = self._clean_text(text)
            if text.strip():
                pages.append(ExtractedPage(
                    content=text,
                    page_number=i + 1,
                    metadata={"source_type": "pdf", "has_images": len(page.images) > 0}
                ))
        return pages

    def _clean_text(self, text: str) -> str:
        import re
        text = re.sub(r'\s+', ' ', text)
        text = re.sub(r'[\x00-\x08\x0b\x0c\x0e-\x1f]', '', text)
        return text.strip()

class DOCXExtractor:
    def extract(self, file_path: str) -> List[ExtractedPage]:
        doc = DocxDocument(file_path)
        pages = []
        current_page = []
        current_heading = ""

        for para in doc.paragraphs:
            if para.style.name.startswith('Heading'):
                if current_page:
                    pages.append(ExtractedPage(
                        content="\n".join(current_page),
                        page_number=len(pages) + 1,
                        metadata={"heading": current_heading, "source_type": "docx"}
                    ))
                    current_page = []
                current_heading = para.text
            current_page.append(para.text)

        if current_page:
            pages.append(ExtractedPage(
                content="\n".join(current_page),
                page_number=len(pages) + 1,
                metadata={"heading": current_heading, "source_type": "docx"}
            ))

        for table in doc.tables:
            table_text = self._extract_table(table)
            if table_text:
                pages.append(ExtractedPage(
                    content=table_text,
                    page_number=len(pages) + 1,
                    metadata={"type": "table", "source_type": "docx"}
                ))
        return pages

    def _extract_table(self, table) -> str:
        rows = []
        for row in table.rows:
            cells = [cell.text.strip() for cell in row.cells]
            rows.append(" | ".join(cells))
        return "\n".join(rows)

class TXTExtractor:
    def extract(self, file_path: str) -> List[ExtractedPage]:
        with open(file_path, 'rb') as f:
            raw = f.read()
        detected = chardet.detect(raw)
        encoding = detected['encoding'] or 'utf-8'
        text = raw.decode(encoding, errors='replace')

        lines = text.split('\n')
        pages = []
        chunk = []
        for i, line in enumerate(lines):
            chunk.append(line)
            if len(chunk) >= 100:
                pages.append(ExtractedPage(
                    content="\n".join(chunk),
                    page_number=len(pages) + 1,
                    metadata={"encoding": encoding, "source_type": "txt"}
                ))
                chunk = []
        if chunk:
            pages.append(ExtractedPage(
                content="\n".join(chunk),
                page_number=len(pages) + 1,
                metadata={"encoding": encoding, "source_type": "txt"}
            ))
        return pages

def get_extractor(file_type: str):
    extractors = {"pdf": PDFExtractor(), "docx": DOCXExtractor(), "txt": TXTExtractor()}
    if file_type not in extractors:
        raise ValueError(f"Desteklenmeyen dosya tipi: {file_type}")
    return extractors[file_type]

