import re
from typing import List
import tiktoken

class SentenceChunker:
    def __init__(self, chunk_size: int = 512, chunk_overlap_sentences: int = 1):
        self.chunk_size = chunk_size
        self.overlap_sentences = chunk_overlap_sentences
        self.tokenizer = tiktoken.encoding_for_model("text-embedding-3-small")

    def _split_sentences(self, text: str) -> List[str]:
        pattern = r'(?<=[.!?])\s+(?=[A-ZÇĞIÖŞÜA-Za-z])'
        sentences = re.split(pattern, text)
        merged = []
        buffer = ""
        for s in sentences:
            if len(self.tokenizer.encode(buffer + " " + s)) < 50 and buffer:
                buffer += " " + s
            else:
                if buffer:
                    merged.append(buffer.strip())
                buffer = s
        if buffer:
            merged.append(buffer.strip())
        return merged

    def chunk(self, pages: list, doc_id: str) -> List[Chunk]:
        chunks = []

        for page in pages:
            sentences = self._split_sentences(page.content)
            current_sentences = []
            current_tokens = 0

            for sentence in sentences:
                sentence_tokens = len(self.tokenizer.encode(sentence))

                if current_tokens + sentence_tokens > self.chunk_size and current_sentences:
                    chunks.append(Chunk(
                        content=" ".join(current_sentences),
                        metadata={
                            "doc_id": doc_id,
                            "page_number": page.page_number,
                            "chunk_index": len(chunks),
                            "chunk_strategy": "sentence",
                            "sentence_count": len(current_sentences),
                            "token_count": current_tokens,
                        },
                        token_count=current_tokens
                    ))

                    current_sentences = current_sentences[-self.overlap_sentences:]
                    current_tokens = sum(len(self.tokenizer.encode(s)) for s in current_sentences)

                current_sentences.append(sentence)
                current_tokens += sentence_tokens

            if current_sentences:
                chunks.append(Chunk(
                    content=" ".join(current_sentences),
                    metadata={
                        "doc_id": doc_id,
                        "page_number": page.page_number,
                        "chunk_index": len(chunks),
                        "chunk_strategy": "sentence",
                        "sentence_count": len(current_sentences),
                        "token_count": current_tokens,
                    },
                    token_count=current_tokens
                ))

        return chunks

