from openai import OpenAI
import hashlib
import time
import logging
from typing import List

logger = logging.getLogger(__name__)

class EmbeddingService:
    def __init__(self, model: str = "text-embedding-3-small", batch_size: int = 100):
        self.client = OpenAI()
        self.model = model
        self.batch_size = batch_size
        self._cache: dict[str, list[float]] = {}

    def _text_hash(self, text: str) -> str:
        return hashlib.md5(text.encode()).hexdigest()

    def embed_texts(self, texts: List[str]) -> List[List[float]]:
        all_embeddings = [None] * len(texts)
        texts_to_embed = []

        for i, text in enumerate(texts):
            cache_key = self._text_hash(text)
            if cache_key in self._cache:
                all_embeddings[i] = self._cache[cache_key]
            else:
                texts_to_embed.append((i, text))

        cache_hits = len(texts) - len(texts_to_embed)
        if cache_hits > 0:
            logger.info(f"Embedding cache: {cache_hits}/{len(texts)} hits")

        for batch_start in range(0, len(texts_to_embed), self.batch_size):
            batch = texts_to_embed[batch_start:batch_start + self.batch_size]
            batch_texts = [t[1] for t in batch]

            try:
                response = self.client.embeddings.create(
                    model=self.model,
                    input=batch_texts
                )

                for j, embedding_data in enumerate(response.data):
                    original_idx = batch[j][0]
                    embedding = embedding_data.embedding
                    all_embeddings[original_idx] = embedding

                    cache_key = self._text_hash(batch_texts[j])
                    self._cache[cache_key] = embedding

                logger.info(f"Embedded batch {batch_start//self.batch_size + 1}, "
                           f"dimension={len(response.data[0].embedding)}, "
                           f"tokens={response.usage.total_tokens}")

            except Exception as e:
                if "rate_limit" in str(e).lower():
                    logger.warning("Rate limited, waiting 10s...")
                    time.sleep(10)
                    return self.embed_texts(texts)
                raise

            if batch_start + self.batch_size < len(texts_to_embed):
                time.sleep(0.5)

        return all_embeddings

    def embed_query(self, query: str) -> List[float]:
        response = self.client.embeddings.create(
            model=self.model,
            input=query
        )
        return response.data[0].embedding

