from rank_bm25 import BM25Okapi
import re
from typing import List, Dict

class BM25Retriever:
    def __init__(self):
        self.bm25 = None
        self.chunks = []

    def _tokenize(self, text: str) -> List[str]:
        text = text.lower()
        text = re.sub(r'[^a-zçğıöşüa-z0-9\s]', ' ', text)
        tokens = text.split()
        stop_words = {'ve', 'bir', 'bu', 'da', 'de', 'ile', 'için', 'olan', 'the', 'and', 'is', 'of', 'to', 'in'}
        return [t for t in tokens if t not in stop_words and len(t) > 1]

    def index(self, chunks: List[Dict]):
        self.chunks = chunks
        tokenized_corpus = [self._tokenize(c["text"]) for c in chunks]
        self.bm25 = BM25Okapi(tokenized_corpus)

    def search(self, query: str, n_results: int = 10) -> List[Dict]:
        if not self.bm25:
            return []

        tokenized_query = self._tokenize(query)
        scores = self.bm25.get_scores(tokenized_query)
        top_indices = scores.argsort()[-n_results:][::-1]

        results = []
        for idx in top_indices:
            if scores[idx] > 0:
                results.append({
                    "id": self.chunks[idx].get("id"),
                    "text": self.chunks[idx]["text"],
                    "metadata": self.chunks[idx].get("metadata", {}),
                    "bm25_score": float(scores[idx]),
                })
        return results

