import re
from typing import List, Dict
from dataclasses import dataclass

@dataclass
class Citation:
    source_index: int
    document_name: str
    page_number: int
    cited_text: str
    chunk_text: str
    relevance_score: float
    start_char: int
    end_char: int

class CitationEngine:
    def extract_citations(
        self, answer: str, retrieved_chunks: List[Dict],
    ) -> List[Citation]:
        citations = []
        patterns = [
            r'\[Kaynak:\s*(.+?),\s*Sayfa:\s*(\d+)\]',
            r'\[Kaynak\s*(\d+)\]',
        ]

        for pattern in patterns:
            for match in re.finditer(pattern, answer):
                if len(match.groups()) == 2:
                    doc_name = match.group(1)
                    page = int(match.group(2))
                    chunk = self._find_matching_chunk(retrieved_chunks, doc_name, page)
                elif len(match.groups()) == 1:
                    idx = int(match.group(1)) - 1
                    if 0 <= idx < len(retrieved_chunks):
                        chunk = retrieved_chunks[idx]
                        doc_name = chunk["metadata"].get("filename", "?")
                        page = chunk["metadata"].get("page_number", 0)
                    else:
                        continue
                else:
                    continue

                if chunk:
                    citations.append(Citation(
                        source_index=len(citations) + 1,
                        document_name=doc_name,
                        page_number=page,
                        cited_text=self._extract_surrounding_text(answer, match.start(), 100),
                        chunk_text=chunk["text"],
                        relevance_score=chunk.get("rerank_score", 0),
                        start_char=match.start(),
                        end_char=match.end(),
                    ))
        return citations

    def _find_matching_chunk(self, chunks, doc_name, page):
        for chunk in chunks:
            if (chunk["metadata"].get("filename", "") == doc_name and
                chunk["metadata"].get("page_number", 0) == page):
                return chunk
        return None

    def _extract_surrounding_text(self, text, position, radius):
        start = max(0, position - radius)
        end = min(len(text), position + radius)
        return text[start:end].strip()

    def format_citations_for_frontend(self, citations: List[Citation]) -> List[Dict]:
        return [
            {
                "index": c.source_index, "document": c.document_name,
                "page": c.page_number, "preview": c.chunk_text[:200],
