        self, message_id: str, rating: str, comment: Optional[str] = None,
    ) -> Dict:
        feedback = QueryFeedback(
            id=str(uuid4()), message_id=message_id,
            rating=rating, comment=comment,
        )
        self.db.add(feedback)
        self.db.commit()

        if rating == "negative":
            return await self._analyze_negative(message_id)
        return {"status": "recorded"}

    async def _analyze_negative(self, message_id: str) -> Dict:
        message = self.db.query(ChatMessage).filter(ChatMessage.id == message_id).first()
        if not message or not message.sources:
            return {"analysis": "insufficient_data"}

        sources = message.sources
        avg_score = sum(s.get("score", 0) for s in sources) / len(sources) if sources else 0

        if avg_score < 0.3:
            cause = "retrieval_failure"
            suggestion = "Chunking stratejisini veya embedding modelini gözden geçir"
        elif avg_score < 0.6:
            cause = "partial_retrieval"
            suggestion = "Hybrid retrieval alpha değerini ayarla veya daha fazla chunk getir"
        else:
            cause = "generation_failure"
            suggestion = "Prompt template'i iyileştir veya temperature'ı düşür"

        return {
            "analysis": cause,
            "avg_retrieval_score": round(avg_score, 3),
            "suggestion": suggestion,
        }

