        since = datetime.utcnow() - timedelta(days=days)
        total_queries = self.db.query(ChatMessage)\
            .filter(ChatMessage.role == "user", ChatMessage.created_at >= since).count()
        feedbacks = self.db.query(QueryFeedback)\
            .filter(QueryFeedback.created_at >= since).all()
        positive = sum(1 for f in feedbacks if f.rating == "positive")
