import hashlib
import json
from typing import Optional, Any
from datetime import datetime, timedelta
from functools import wraps
import numpy as np

class RAGCache:
    def __init__(self):
        self._cache = {}

    def _make_key(self, prefix: str, *args) -> str:
        content = json.dumps(args, sort_keys=True, default=str)
        return f"{prefix}:{hashlib.md5(content.encode()).hexdigest()}"

    def get(self, key: str) -> Optional[Any]:
        if key in self._cache:
            entry = self._cache[key]
            if entry["expires_at"] > datetime.utcnow(): return entry["value"]
            del self._cache[key]
        return None

    def set(self, key: str, value: Any, ttl_seconds: int = 3600):
        self._cache[key] = {"value": value, "expires_at": datetime.utcnow() + timedelta(seconds=ttl_seconds)}

    def invalidate_collection(self, collection_name: str):
        keys_to_delete = [k for k in self._cache if collection_name in k]
        for key in keys_to_delete: del self._cache[key]

class SemanticCache:
    def __init__(self, embedding_service, similarity_threshold=0.95):
        self.embedding_service = embedding_service
        self.threshold = similarity_threshold
        self.entries = []

    async def get_similar(self, query: str):
        query_emb = self.embedding_service.embed_query(query)
        for emb, cached_query, response in self.entries:
            similarity = np.dot(query_emb, emb) / (np.linalg.norm(query_emb) * np.linalg.norm(emb))
            if similarity > self.threshold:
                return {"cached_query": cached_query, "response": response}
        return None

